const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define northwestern Pennsylvania region
  const nwPennsylvania = ee.Geometry.Polygon([
    [[-80.5, 42.0], [-80.5, 41.5], [-79.5, 41.5], [-79.5, 42.0], [-80.5, 42.0]]
  ]);

  // Define dates
  const date1 = '2020-02-22';
  const date2 = '2020-03-01';

  try {
    // Get MODIS snow cover data
    const snowCol1 = ee.ImageCollection('MODIS/006/MOD10A1')
      .filterDate(date1, ee.Date(date1).advance(1, 'day'))
      .filterBounds(nwPennsylvania);

    const snowCol2 = ee.ImageCollection('MODIS/006/MOD10A1')
      .filterDate(date2, ee.Date(date2).advance(1, 'day'))
      .filterBounds(nwPennsylvania);

    const size1 = await snowCol1.size().getInfo();
    const size2 = await snowCol2.size().getInfo();

    console.log(`Feb 22 images: ${size1}, Mar 1 images: ${size2}`);

    if (size1 === 0 || size2 === 0) {
      console.log("Missing data for one or both dates");
      console.log("<answer>C1</answer>");
      return;
    }

    // Get the images
    const img1 = snowCol1.first();
    const img2 = snowCol2.first();

    // NDSI_Snow_Cover band: 0-100 (percent snow cover), 200=missing, 201=no decision, 211=night, 237=inland water, 239=ocean, 250=cloud, 254=detector saturated, 255=fill
    // Mask out non-snow values (keep only 0-100)
    const snowBand1 = img1.select('NDSI_Snow_Cover').updateMask(
      img1.select('NDSI_Snow_Cover').gte(0).and(img1.select('NDSI_Snow_Cover').lte(100))
    );

    const snowBand2 = img2.select('NDSI_Snow_Cover').updateMask(
      img2.select('NDSI_Snow_Cover').gte(0).and(img2.select('NDSI_Snow_Cover').lte(100))
    );

    // Calculate statistics
    const stats1 = await snowBand1.reduceRegion({
      reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
      geometry: nwPennsylvania,
      scale: 500,
      maxPixels: 1e9
    }).getInfo();

    const stats2 = await snowBand2.reduceRegion({
      reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
      geometry: nwPennsylvania,
      scale: 500,
      maxPixels: 1e9
    }).getInfo();

    const mean1 = stats1['NDSI_Snow_Cover_mean'];
    const count1 = stats1['NDSI_Snow_Cover_count'];
    const mean2 = stats2['NDSI_Snow_Cover_mean'];
    const count2 = stats2['NDSI_Snow_Cover_count'];

    console.log(`Feb 22: Mean=${mean1?.toFixed(2)}%, Pixels=${count1}`);
    console.log(`Mar 1: Mean=${mean2?.toFixed(2)}%, Pixels=${count2}`);

    if (count1 === 0 || count2 === 0) {
      console.log("No valid pixels after masking");
      console.log("<answer>C2</answer>");
      return;
    }

    if (mean1 === null || mean1 === undefined || mean2 === null || mean2 === undefined) {
      console.log("Calculation failed");
      console.log("<answer>C3</answer>");
      return;
    }

    if (isNaN(mean1) || isNaN(mean2) || mean1 < 0 || mean1 > 100 || mean2 < 0 || mean2 > 100) {
      console.log("Invalid snow cover values");
      console.log("<answer>C3</answer>");
      return;
    }

    // Compare snow cover
    if (mean2 > mean1) {
      console.log(`Snow cover increased from ${mean1.toFixed(2)}% to ${mean2.toFixed(2)}%`);
      console.log("<answer>A</answer>");
    } else {
      console.log(`Snow cover did not increase (${mean1.toFixed(2)}% to ${mean2.toFixed(2)}%)`);
      console.log("<answer>B</answer>");
    }

  } catch (error) {
    console.log(`Error: ${error.message}`);
    console.log("<answer>D</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
